def format_long_text(text: str, color: str='', columns: int=
    get_terminal_size().columns, start_line_decorator: str=' ',
    end_line_decorator: str=' ', max_lines: Optional[int]=None, styling:
    Optional[Dict[str, Any]]=None, indent: str='', sub_indent: str='') ->str:
    if not text:
        return ''

    if styling is None:
        styling = {}

    wrapped_lines = textwrap.wrap(text, width=columns - len(start_line_decorator) - len(end_line_decorator))

    if max_lines and len(wrapped_lines) > max_lines:
        wrapped_lines = wrapped_lines[:max_lines]
        if wrapped_lines:
            wrapped_lines[-1] += '...'

    if not wrapped_lines:
        wrapped_lines = [text]

    formatted_lines = []
    for i, line in enumerate(wrapped_lines):
        if i == 0:
            formatted_line = start_line_decorator + indent + line + end_line_decorator
        else:
            formatted_line = start_line_decorator + sub_indent + line + end_line_decorator

        if color:
            formatted_line = click.style(formatted_line, fg=color, **styling)

        formatted_lines.append(formatted_line)

    return '\n'.join(formatted_lines)
